":"2026-10-11T00:00:00+07:00","effective_to":"2026-10-12T00:00:00+07:00"},{"approval_type":"menu_item","menu_item_id":"f5f80cd7-c866-4e87-bc05-5c606c889881","item_type":null,"invoice_name_vi":"Gà Không Xương Sốt Phô Mai Cay","unit_name":"Phần","mapping_version":"AKJ-MANUAL-20261011-v1","source_reference":"AKJ_MISA_매출신고_2026-10-11_MISA수정.xlsx / sha256:6741a79e3b92f5dbbaad11465c7a399a1ea56aa1c3168f17b1dab6353d417386","effective_from":"2026-10-11T00:00:00+07:00","effective_to":"2026-10-12T00:00:00+07:00"},{"approval_type":"menu_item","menu_item_id":"fa07054d-d80e-4f11-bc94-fcda3169cbcc","item_type":null,"invoice_name_vi":"Cơm Chiên Cá Ngừ Kimchi","unit_name":"Phần","mapping_version":"AKJ-MANUAL-20261011-v1","source_reference":"AKJ_MISA_매출신고_2026-10-11_MISA수정.xlsx / sha256:6741a79e3b92f5dbbaad11465c7a399a1ea56aa1c3168f17b1dab6353d417386","effective_from":"2026-10-11T00:00:00+07:00","effective_to":"2026-10-12T00:00:00+07:00"},{"approval_type":"menu_item","menu_item_id":"fd70a75b-057d-4c3f-97ba-205de1851910","item_type":null,"invoice_name_vi":"Udon Đậu Hũ Hải Sản","unit_name":"Phần","mapping_version":"AKJ-MANUAL-20261011-v1","source_reference":"AKJ_MISA_매출신고_2026-10-11_MISA수정.xlsx / sha256:6741a79e3b92f5dbbaad11465c7a399a1ea56aa1c3168f17b1dab6353d417386","effective_from":"2026-10-11T00:00:00+07:00","effective_to":"2026-10-12T00:00:00+07:00"},{"approval_type":"menu_item","menu_item_id":"ff543901-95ba-41bf-81c2-c55b0b7650b4","item_type":null,"invoice_name_vi":"Kimbap Cá Ngừ","unit_name":"Phần","mapping_version":"AKJ-MANUAL-20261011-v1","source_reference":"AKJ_MISA_매출신고_2026-10-11_MISA수정.xlsx / sha256:6741a79e3b92f5dbbaad11465c7a399a1ea56aa1c3168f17b1dab6353d417386","effective_from":"2026-10-11T00:00:00+07:00","effective_to":"2026-10-12T00:00:00+07:00"},{"approval_type":"item_type","menu_item_id":null,"item_type":"wet_tissue_charge","invoice_name_vi":"Khăn ướt","unit_name":"Cái","mapping_version":"AKJ-MANUAL-20261011-v1","source_reference":"AKJ_MISA_매출신고_2026-10-11_MISA수정.xlsx / sha256:6741a79e3b92f5dbbaad11465c7a399a1ea56aa1c3168f17b1dab6353d417386","effective_from":"2026-10-11T00:00:00+07:00","effective_to":"2026-10-12T00:00:00+07:00","store_names":["BunsikClub Binh Thanh"]}],"source_contracts":[{"source_system":"photo_objet_moers","invoice_name_vi":"Dịch vụ chụp ảnh","unit_name":"Lần","mapping_version":"AKJ-MANUAL-20261011-v1"}]}_DRIFT'; END IF;
 IF now()<'2026-10-12 00:00+07'::timestamptz THEN RAISE EXCEPTION 'INITIAL_MAPPING_PERIOD_NOT_CLOSED'; END IF;
 SELECT count(*),(array_agg(auth_id))[1] INTO owner_count,owner_auth_id FROM public.users
 WHERE role='super_admin' AND is_active AND auth_id IS NOT NULL;
 IF owner_count<>(CASE WHEN fresh_install THEN 0 ELSE 1 END) THEN RAISE EXCEPTION 'INITIAL_MAPPING_APPROVING_OWNER_AMBIGUOUS'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(input->'rows') x JOIN public.menu_items m ON m.id=(x->>'menu_item_id')::uuid
 JOIN public.restaurants r ON r.id=m.restaurant_id WHERE x->>'approval_type'='menu_item' AND r.tax_entity_id=seller)<>(CASE WHEN fresh_install THEN 0 ELSE 73 END)
 OR (SELECT count(*) FROM public.restaurants WHERE tax_entity_id=seller AND name='BunsikClub Binh Thanh')<>(CASE WHEN fresh_install THEN 0 ELSE 1 END)
 THEN RAISE EXCEPTION 'INITIAL_MAPPING_PRODUCTION_SCOPE_DRIFT'; END IF;
 SELECT md5(string_agg(to_jsonb(m)::text,',' ORDER BY id)) INTO before_master FROM public.menu_items m;
 PERFORM set_config('request.jwt.claim.sub',owner_auth_id::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',owner_auth_id,'role','authenticated')::text,true);
 FOR group_row IN
 WITH expanded AS (
 SELECT m.restaurant_id AS store_id,x AS row FROM jsonb_array_elements(input->'rows') x
 JOIN public.menu_items m ON m.id=(x->>'menu_item_id')::uuid WHERE x->>'approval_type'='menu_item'
 UNION ALL
 SELECT r.id,x-'store_names' FROM jsonb_array_elements(input->'rows') x
 CROSS JOIN LATERAL jsonb_array_elements_text(x->'store_names') names(store_name)
 JOIN public.restaurants r ON r.name=names.store_name AND r.tax_entity_id=seller WHERE x->>'approval_type'='item_type')
 SELECT store_id,jsonb_agg(row ORDER BY row->>'menu_item_id',row->>'item_type') AS rows FROM expanded GROUP BY store_id ORDER BY store_id
 LOOP
  IF jsonb_array_length(group_row.rows)>100 THEN RAISE EXCEPTION 'INITIAL_MAPPING_BATCH_LIMIT'; END IF;
  result:=public.approve_invoice_mapping_batch(group_row.store_id,seller,group_row.rows);
  IF result->>'store_id'<>group_row.store_id::text OR result->>'tax_entity_id'<>seller::text
   OR jsonb_array_length(result->'profiles')<>jsonb_array_length(group_row.rows)
  THEN RAISE EXCEPTION 'INITIAL_MAPPING_APPROVAL_RESULT_DRIFT'; END IF;
  expected:=expected+jsonb_array_length(group_row.rows);
 END LOOP;
 SELECT count(*) INTO actual FROM public.invoice_approved_profiles p
 WHERE p.tax_entity_id=seller AND p.mapping_version='AKJ-MANUAL-20261011-v1'
 AND p.effective_from='2026-10-11 00:00+07'::timestamptz AND p.effective_to='2026-10-12 00:00+07'::timestamptz;
 SELECT md5(string_agg(to_jsonb(m)::text,',' ORDER BY id)) INTO after_master FROM public.menu_items m;
 IF expected<>(CASE WHEN fresh_install THEN 0 ELSE 74 END) OR actual<>expected OR before_master IS DISTINCT FROM after_master
 THEN RAISE EXCEPTION 'INITIAL_MAPPING_POSTCONDITION_FAILED'; END IF;
 PERFORM set_config('request.jwt.claim.sub',COALESCE(old_sub,''),true);
 PERFORM set_config('request.jwt.claims',COALESCE(old_claims,'{}'),true);
 RAISE NOTICE 'INITIAL_INVOICE_MAPPING_REGISTERED=% (historical 2026-10-11 subjects only)', actual;
END $initial$;
COMMIT;
